syntax:
const char *match_results[]; // array of pointers to matched substrings
// Access subexpression at position n:
// match_results[n]
// For example, to get the substring for subexpression n:
// const char *subexpr_start = match_results[n];
// size_t subexpr_length = match_results[n+1] - match_results[n]; // if end pointer is known

code_example:
regex_t regex;
regmatch_t pmatch[3]; // array to hold full match and submatches
if (regexec(&regex, input_string, 3, pmatch, 0) == 0) {
    // pmatch[0] is the entire match
    // pmatch[1] is the first subexpression
    // pmatch[2] is the second subexpression
    printf("Filename: %.*s\n", pmatch[1].rm_eo - pmatch[1].rm_so, input_string + pmatch[1].rm_so);
}
